SELECT k.KasaHareketID, Format(k.Tarih,"dd.mm.yyyy") AS Tarih, k.MusteriID, m.AdSoyad AS Müşteri, p.PartiKodu AS Parti, k.HareketTuru AS Hareket, k.OdemeYontemi AS Yöntem, k.Aciklama AS Açıklama, Format(Nz(k.Tahsilat,0),"#,##0.00") AS Tahsilat, Format(Nz(k.Odeme,0),"#,##0.00") AS Ödeme, Format(Nz(ks.AcilisBakiyesi,0)+Nz((SELECT Sum(Nz(x.Tahsilat,0)-Nz(x.Odeme,0)) FROM tbl_KasaHareket AS x WHERE x.KasaID=k.KasaID AND x.IptalMi=False AND (x.Tarih<k.Tarih OR (x.Tarih=k.Tarih AND x.KasaHareketID<=k.KasaHareketID))),0),"#,##0.00") AS Bakiye, Switch(Nz(k.KaynakTipi,"")="PARTI","Üretim",Nz(k.KaynakTipi,"")="TESLIM","Teslim",Nz(k.KaynakTipi,"")="KASA","Kasa/Banka",Nz(k.KaynakTipi,"")="ALIMSATIM","Alım/Satım",True,"Manuel") AS Kaynak, k.Tarih AS TarihHam, k.KasaID
FROM ((tbl_KasaHareket AS k LEFT JOIN tbl_Musteri AS m ON k.MusteriID=m.MusteriID) LEFT JOIN tbl_Parti AS p ON k.PartiNo=p.PartiNo) LEFT JOIN tbl_Kasa AS ks ON k.KasaID=ks.KasaID
WHERE k.IptalMi=False;